import { and, eq, isNull, type SQL, sql } from "drizzle-orm";
import type { Db } from "../client.ts";
import {
  memberships,
  type RepoPermission,
  repoAccess,
  repos,
  workspaces,
} from "../schema/index.ts";
import { queryJson, timeParam } from "./json.ts";
import { run } from "./run.ts";

/*
 * A repo's ideas: four prompts to start a design from, generated by the API (`ideas/` there)
 * and kept on `repos.ideas`, one list per repo for everyone who can read it. A generation is
 * claimed in the row, so one instance at a time does it, and counted against its workspace's
 * allowance, so a workspace with a thousand repos cannot run up the bill.
 */

/** A repo as deciding whether to show or start its ideas needs it. */
export interface RepoIdeasRow {
  id: string;
  workspaceId: string;
  githubRepoId: number;
  fullName: string;
  defaultBranch: string;
  pushedAt: Date | null;
  ideas: string[];
  ideasGeneratedAt: Date | null;
  ideasClaimedAt: Date | null;
}

/** A repo's ideas with what deciding whether `userId` may read them takes. */
export interface RepoIdeasAccess {
  repo: RepoIdeasRow;
  /** The App's installation on the repo's workspace. Null while the App is not installed. */
  installationId: number | null;
  /** Set while the App is suspended on the workspace. */
  suspendedAt: Date | null;
  /** What GitHub last said the person may do in the repo, if it was ever asked. */
  known: { permission: RepoPermission; checkedAt: Date } | null;
  /** Whether the person is a member of the repo's workspace. Nobody else may read it. */
  member: boolean;
}

/**
 * A repo the App still sees, with its ideas and what deciding whether `userId` may read it
 * takes (as `getDesignAccess` has it for a design), or null when there is no such repo.
 */
export async function getRepoIdeasAccess(
  db: Db,
  { repoId, userId }: { repoId: string; userId: string },
): Promise<RepoIdeasAccess | null> {
  const [row] = await run(
    db
      .select({
        repo: {
          id: repos.id,
          workspaceId: repos.workspaceId,
          githubRepoId: repos.githubRepoId,
          fullName: repos.fullName,
          defaultBranch: repos.defaultBranch,
          pushedAt: repos.pushedAt,
          ideas: repos.ideas,
          ideasGeneratedAt: repos.ideasGeneratedAt,
          ideasClaimedAt: repos.ideasClaimedAt,
        },
        installationId: workspaces.installationId,
        suspendedAt: workspaces.suspendedAt,
        permission: repoAccess.permission,
        checkedAt: repoAccess.checkedAt,
        member: sql<boolean>`${memberships.userId} is not null`.mapWith(Boolean),
      })
      .from(repos)
      .innerJoin(workspaces, eq(workspaces.id, repos.workspaceId))
      .leftJoin(
        memberships,
        and(eq(memberships.workspaceId, repos.workspaceId), eq(memberships.userId, userId)),
      )
      .leftJoin(repoAccess, and(eq(repoAccess.repoId, repos.id), eq(repoAccess.userId, userId)))
      .where(and(eq(repos.id, repoId), isNull(repos.removedAt))),
  );
  if (!row) return null;
  const { repo, installationId, suspendedAt, permission, checkedAt, member } = row;
  return {
    repo,
    installationId,
    suspendedAt,
    known: permission === null || checkedAt === null ? null : { permission, checkedAt },
    member,
  };
}

/** When a repo's ideas are due to be generated, as `claimRepoIdeas` is told it. */
export interface IdeasPolicy {
  now: Date;
  /** A claim taken at or before this may be taken again: the last try finished or died. */
  retryBefore: Date;
  /** Ideas written at or before this are old enough to make again, if the repo was pushed since. */
  staleBefore: Date;
  /** A workspace's window that began at or before this is over, and a new one begins. */
  windowStartedBefore: Date;
  /** How many generations one workspace may start in one window. */
  windowLimit: number;
}

export type IdeasClaim =
  /** This caller generates them now, and its claim is `now`. */
  | "claimed"
  /** Nothing is due: they are fresh, or a generation is under way or was tried lately. */
  | "not_due"
  /** Due, and the workspace has used its allowance for now. */
  | "rate_limited";

/**
 * Take on generating a repo's ideas, if they are due and nobody has them in hand, and count
 * it against the workspace's allowance. One statement: the workspace's row is locked while
 * its count is checked and moved, so two repos of one workspace claimed at once cannot both
 * take its last generation. Two requests for the same repo at once can both spend one, and
 * only one of them claims it; the allowance errs that way, never the other.
 *
 * Due: never generated; or generated empty, or at or before `staleBefore`, and pushed since.
 */
export async function claimRepoIdeas(
  db: Db,
  { repoId, ...policy }: IdeasPolicy & { repoId: string },
): Promise<IdeasClaim> {
  const now = timeParam(policy.now);
  const windowOver = sql`(workspaces.ideas_window_started_at is null
    or workspaces.ideas_window_started_at <= ${timeParam(policy.windowStartedBefore)}::timestamptz)`;
  const result = await queryJson<{ due: boolean; quota: boolean; claimed: boolean }>(
    db,
    sql`
      with target as (
        select repos.id, repos.workspace_id from repos where repos.id = ${repoId} and ${due(policy)}
      ), quota as (
        update workspaces set
          ideas_window_started_at = case when ${windowOver} then ${now}::timestamptz
            else workspaces.ideas_window_started_at end,
          ideas_window_count = case when ${windowOver} then 1
            else workspaces.ideas_window_count + 1 end
        from target
        where workspaces.id = target.workspace_id
          and (${windowOver} or workspaces.ideas_window_count < ${policy.windowLimit})
        returning workspaces.id
      ), claimed as (
        update repos set ideas_claimed_at = ${now}::timestamptz
        where repos.id = ${repoId} and ${due(policy)} and exists (select 1 from quota)
        returning repos.id
      )
      select json_build_object(
        'due', exists (select 1 from target),
        'quota', exists (select 1 from quota),
        'claimed', exists (select 1 from claimed)
      ) as result`,
  );
  if (result?.claimed) return "claimed";
  return result?.due && !result.quota ? "rate_limited" : "not_due";
}

/** The repo's ideas are due, by `policy`: what `claimRepoIdeas` takes. */
function due(policy: IdeasPolicy): SQL {
  return sql`repos.removed_at is null
    and (repos.ideas_claimed_at is null
      or repos.ideas_claimed_at <= ${timeParam(policy.retryBefore)}::timestamptz)
    and (repos.ideas_generated_at is null
      or (repos.pushed_at > repos.ideas_generated_at
        and (jsonb_array_length(repos.ideas) = 0
          or repos.ideas_generated_at <= ${timeParam(policy.staleBefore)}::timestamptz)))`;
}

/**
 * Keep the ideas a generation made (an empty list when there were none to make), as of
 * `generatedAt`. Only the claim that made them writes: false, and nothing written, once
 * another has been taken since (this one ran past its time).
 */
export async function saveRepoIdeas(
  db: Db,
  {
    repoId,
    ideas,
    generatedAt,
    claimedAt,
  }: { repoId: string; ideas: string[]; generatedAt: Date; claimedAt: Date },
): Promise<boolean> {
  const saved = await run(
    db
      .update(repos)
      .set({ ideas, ideasGeneratedAt: generatedAt })
      .where(and(eq(repos.id, repoId), eq(repos.ideasClaimedAt, claimedAt)))
      .returning({ id: repos.id }),
  );
  return saved.length > 0;
}

/**
 * End a claim that kept nothing (the try failed) by moving it back to `to`: early enough that
 * it no longer reads as a generation under way, and the wait before the next try counts from
 * there. Nothing changes once another claim has been taken since.
 */
export async function releaseRepoIdeas(
  db: Db,
  { repoId, claimedAt, to }: { repoId: string; claimedAt: Date; to: Date },
): Promise<void> {
  await run(
    db
      .update(repos)
      .set({ ideasClaimedAt: to })
      .where(and(eq(repos.id, repoId), eq(repos.ideasClaimedAt, claimedAt))),
  );
}
